{
  "entities": [
    {
      "id": "e1",
      "name": "Dinnis",
      "type": "person",
      "evidence": "'tis aisy to see that ye've not had mich expeerunce o' jew'ls, me bye, or ye'd not mistake these bits o' glass an' sich fer thim."
    },
    {
      "id": "e2",
      "name": "Honor",
      "type": "person",
      "evidence": "\"Ivery toime, yer Anner!\" said Honor."
    },
    {
      "id": "e3",
      "name": "Mrs. Macarthy",
      "type": "person",
      "evidence": "\"Och, whirrasthru!\" cried Mrs. Macarthy."
    },
    {
      "id": "e4",
      "name": "Dr. O'Shaughnessy",
      "type": "person",
      "evidence": "Holding her as in a vice, Dr. O'Shaughnessy spoke once more to her parents."
    },
    {
      "id": "e5",
      "name": "Eileen",
      "type": "person",
      "evidence": "she found herself seized... while another hand covered her mouth... Dr. O'Shaughnessy... and Misthress O'Shaughnessy will tind her as if she wuz her own"
    },
    {
      "id": "e6",
      "name": "the Countess's",
      "type": "place",
      "evidence": "there's no jew'ls here, wheriver the Countess's are."
    },
    {
      "id": "e7",
      "name": "Misthress O'Shaughnessy",
      "type": "person",
      "evidence": "and Misthress O'Shaughnessy will tind her as if she wuz her own"
    },
    {
      "id": "e8",
      "name": "Dr. Macarthy",
      "type": "person",
      "evidence": "\"I see!\" said the doctor. \"I understand. This is a very sirrious case, Misther Macarthy...\""
    },
    {
      "id": "e9",
      "name": "mint",
      "type": "plant",
      "evidence": "\"Spirimint?\" said Honor. \"Sure, there's two, three kinds o' mint growin' here in oor own door\""
    }
  ],
  "relations": [
    {
      "source": "e1",
      "predicate": "is addressed by",
      "target": "e8",
      "evidence": "\"Why, Dinnis,\" he said..."
    },
    {
      "source": "e2",
      "predicate": "responds to",
      "target": "e3",
      "evidence": "\"Ochone! ochone!\" and in her grief she loosed her hold of Eileen"
    },
    {
      "source": "e4",
      "predicate": "holds",
      "target": "e5",
      "evidence": "Holding her as in a vice, Dr. O'Shaughnessy spoke once more to her parents."
    },
    {
      "source": "e8",
      "predicate": "tells",
      "target": "e1",
      "evidence": "\"I'll be free to till ye that I know but _wan_ way av curin' it.\""
    },
    {
      "source": "e4",
      "predicate": "will take",
      "target": "e5",
      "evidence": "I'll take the choild home wid me to me house, and Misthress O'Shaughnessy will tind her as if she wuz her own"
    },
    {
      "source": "e4",
      "predicate": "will try",
      "target": "e9",
      "evidence": "I'll take the choild home wid me to me house, and Misthress O'Shaughnessy will tind her as if she wuz her own; and thin I will try th' ixpirimint which is the ownly thing on airth can save her."
    },
    {
      "source": "e3",
      "predicate": "sobs for",
      "target": "e5",
      "evidence": "Och, me choild! me poor, diminted choild! will I lose ye this-a-way? Ochone! ochone!"
    },
    {
      "source": "e8",
      "predicate": "is addressed by",
      "target": "e1",
      "evidence": "\"Why, Dinnis,\" he said..."
